import Modal from 'flarum/common/components/Modal';
import Icon from 'flarum/common/components/Icon';
import { uiIcon } from '../uiIcons';
/** Общая связь назначения окна со служебной иконкой. Сами значки по-прежнему
 * задаются в resources/presentation/icons.json, включая локальные замены Pro-иконок.
 */
const headingIcons = {
  create: 'actions.create',
  edit: 'actions.edit',
  grant: 'management.title',
  learn: 'sections.spells',
  history: 'actions.history',
  effects: 'profile.effects',
  approve: 'wizard.review',
  return: 'review.return',
  import: 'actions.import',
  export: 'actions.export',
  complete: 'fields.icon',
  check: 'effects.allChecks'
};

/** Базовое окно расширения. Конкретное окно задаёт название, назначение и классы
 * своего содержимого. Заголовок и общий класс формируются здесь, оформление — в modals.css.
 * Для новых окон наследуем этот класс, сохраняя обычные события и закрытие Modal ядра.
 */
export default class RoleplayModal extends Modal {
  className() {
    return 'RpModal ' + this.modalClassName();
  }
  title() {
    const heading = this.modalHeading();
    return m("span", {
      className: "RpModalHeading"
    }, m("span", {
      className: "RpModalHeading-icon",
      "aria-hidden": "true"
    }, m(Icon, {
      name: uiIcon(headingIcons[heading.purpose])
    })), m("span", {
      className: "RpModalHeading-text"
    }, heading.label));
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/components/RoleplayModal', RoleplayModal);