/** Обратно отправляем только редактируемые поля. Системные ключи не меняются при переименовании. */
export function initialFields(row, defaults) {
  const result = {
    name: row?.name ?? '',
    description: row?.description ?? '',
    enabled: row?.enabled ?? true,
    sort_order: row?.sort_order ?? 0
  };
  for (const [key, value] of Object.entries(defaults)) result[key] = row?.[key] ?? value;
  return result;
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/helpers', { text: text,number: number,object: object,ids: ids,lookup: lookup,options: options,initialFields: initialFields, });