import app from 'flarum/forum/app';
/** Только транспорт. Анкета и окна не считают параметры и не решают, кому разрешены действия. */
export default class ProfileApi {
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay';
  }
  async list(userId, before) {
    const result = await app.request({
      method: 'GET',
      url: this.url() + '/users/' + userId + '/characters',
      params: before === undefined ? {} : {
        before
      },
      errorHandler: () => {}
    });
    return result.data;
  }
  async read(characterId) {
    const result = await app.request({
      method: 'GET',
      url: this.url() + '/characters/' + characterId,
      errorHandler: () => {}
    });
    return result.data;
  }
  equip(id, body) {
    return this.change(id, 'equipment', 'POST', body);
  }
  review(id, body) {
    return this.change(id, 'review', 'POST', body);
  }
  correct(id, body) {
    return this.change(id, 'identity', 'PUT', body);
  }
  progress(id, body) {
    return this.change(id, 'progression', 'POST', body);
  }
  manage(id, body) {
    return this.change(id, 'management', 'POST', body);
  }
  async change(id, path, method, body) {
    const result = await app.request({
      method,
      url: this.url() + '/characters/' + id + '/' + path,
      body,
      errorHandler: () => {}
    });
    return result.data;
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/ProfileApi', ProfileApi);