import app from 'flarum/forum/app';
/** Транспорт только создания. Административные изменение/удаление сюда намеренно не подключены. */
export default class ManagementCatalogApi {
  imageEndpoint = '/roleplay/management/perk-image';
  createdId = null;
  constructor(key) {
    this.key = key;
  }
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/management/catalogs/' + this.key;
  }
  async list() {
    return (await app.request({
      method: 'GET',
      url: this.url(),
      errorHandler: () => {}
    })).data;
  }
  async save(id, revision, fields) {
    if (id !== null) throw new Error('Здесь можно только создать новую сущность.');
    const result = await app.request({
      method: 'POST',
      url: this.url(),
      body: {
        revision,
        fields
      },
      errorHandler: () => {}
    });
    this.createdId = result.data.id;
  }
  async toggle() {
    throw new Error('Переключение справочников доступно в админке.');
  }
  async remove() {
    throw new Error('Удаление справочников доступно в админке.');
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/ManagementCatalogApi', ManagementCatalogApi);