import app from 'flarum/forum/app';
/** Существующая форма редактора, отдельный проверяемый на сервере транспорт. */
export default class WorkspaceCatalogApi {
  imageEndpoint = '/roleplay/management/perk-image';
  constructor(key) {
    this.key = key;
  }
  url(id) {
    return app.forum.attribute('apiUrl') + '/roleplay/workspace/catalogs/' + this.key + (id === undefined ? '' : '/' + id);
  }
  async list(params) {
    return (await app.request({
      method: 'GET',
      url: this.url(),
      params,
      errorHandler: () => {}
    })).data;
  }
  async save(id, revision, fields) {
    await app.request({
      method: id === null ? 'POST' : 'PUT',
      url: this.url(id ?? undefined),
      body: {
        revision,
        fields
      },
      errorHandler: () => {}
    });
  }
  async toggle(id, revision, enabled) {
    await app.request({
      method: 'PATCH',
      url: this.url(id),
      body: {
        revision,
        enabled
      },
      errorHandler: () => {}
    });
  }
  async remove(id, revision) {
    await app.request({
      method: 'DELETE',
      url: this.url(id),
      body: {
        revision
      },
      errorHandler: () => {}
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/workspace/WorkspaceCatalogApi', WorkspaceCatalogApi);