import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import ProfileApi from '../profile/ProfileApi';
import CreationWizardModal from './CreationWizardModal';
import { creationRequiresLogin, creationEmailUnconfirmed } from './creationAccess';
import { requestMessage } from '../../common/requestError';

/** Проверяем актуальный список при нажатии: создание и удаление не оставляют старую ссылку. */
export default class CharacterButton extends Component {
  loading = false;
  disposed = false;
  view() {
    return m(Button, {
      className: "Button",
      icon: "fas fa-user",
      loading: this.loading,
      disabled: !creationRequiresLogin() && !creationEmailUnconfirmed() && !app.forum.attribute('roleplayCanView'),
      onclick: () => void this.open()
    }, "\u041F\u0435\u0440\u0441\u043E\u043D\u0430\u0436");
  }
  onremove() {
    this.disposed = true;
  }
  async open() {
    if (this.loading) return;
    const user = app.session.user;
    if (creationRequiresLogin() || creationEmailUnconfirmed()) {
      await CreationWizardModal.open();
      return;
    }
    if (!user) return;
    const route = m.route.get();
    const current = () => !this.disposed && app.session.user === user && m.route.get() === route;
    this.loading = true;
    try {
      const list = await new ProfileApi().list(Number(user.id()));
      if (!current()) return;
      if (list.characters.length) {
        m.route.set(app.route('user.roleplay', {
          username: user.slug()
        }));
      } else if (app.forum.attribute('roleplayCanCreate')) {
        await CreationWizardModal.open();
      } else {
        app.alerts.show({
          type: 'warning'
        }, 'У вас нет разрешения на создание персонажа');
      }
    } catch (error) {
      if (current()) app.alerts.show({
        type: 'error'
      }, requestMessage(error, 'Не удалось открыть персонажа. Попробуйте ещё раз'));
    } finally {
      this.loading = false;
      m.redraw();
    }
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/creation/CharacterButton', CharacterButton);