import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import showModal from '../../common/showModal';
import { requestMessage } from '../../common/requestError';
import { uiIcon } from '../../common/uiIcons';
import EpisodeCompletionApi from './EpisodeCompletionApi';
import EpisodeCompletionModal from './EpisodeCompletionModal';
export default class CompletionButton extends Component {
  opening = false;
  disposed = false;
  onremove() {
    this.disposed = true;
  }
  view() {
    return m(Button, {
      type: "button",
      className: "Button Button--icon Button--link",
      icon: uiIcon('extension'),
      title: "\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u044D\u043F\u0438\u0437\u043E\u0434\u0430",
      "aria-label": "\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u044D\u043F\u0438\u0437\u043E\u0434\u0430",
      disabled: this.attrs.disabled || this.opening,
      loading: this.opening,
      onclick: () => void this.open()
    });
  }
  async open() {
    if (this.opening || this.attrs.disabled) return;
    const composer = this.attrs.composer,
      editor = composer.editor,
      body = composer.body;
    const user = app.session.user,
      modal = app.modal.modal;
    if (!editor || !user) return;
    const [start] = editor.getSelectionRange();
    const api = new EpisodeCompletionApi(Number(this.attrs.discussion.id()));
    const current = () => !this.disposed && composer.body === body && composer.editor === editor && app.session.user === user;
    this.opening = true;
    m.redraw();
    try {
      const context = await api.context();
      if (!current() || app.modal.modal !== modal) return;
      showModal(EpisodeCompletionModal, {
        context,
        source: api,
        onInsert: async payload => {
          if (!current()) throw new Error('Редактор изменился');
          const code = await api.prepare(payload);
          if (!current()) throw new Error('Редактор изменился');
          editor.insertBetween(start, start, '\n' + code + '\n', true);
          this.attrs.onInserted?.();
        }
      });
    } catch (error) {
      if (current()) app.alerts.show({
        type: 'error'
      }, requestMessage(error, 'Не удалось открыть завершение эпизода. Попробуйте ещё раз'));
    } finally {
      if (!this.disposed) {
        this.opening = false;
        m.redraw();
      }
    }
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/episodes/CompletionButton', CompletionButton);