import Icon from 'flarum/common/components/Icon';
import { catalogueIcon, uiIcon } from '../../uiIcons';
import { initialFields, lookup, text } from '../helpers';
import { safeImage, pathColor } from '../../presentation';
export const statusFilter = {
  key: 'enabled',
  label: 'Все статусы',
  options: () => ({
    '1': 'Включённые',
    '0': 'Выключенные'
  })
};
export function referenceFilter(key, label, catalogue) {
  return {
    key,
    label,
    options: lookups => Object.fromEntries((lookups[catalogue] ?? []).map(row => [String(row.id), row.name]))
  };
}
/** У каждого раздела свой небольшой файл. Общие возможности задаются здесь один раз. */
export function definition(value) {
  return {
    endpoint: 'catalogs/' + value.key,
    filters: [statusFilter],
    create: true,
    toggle: true,
    remove: true,
    revision: (_row, result) => result.revision,
    initial: row => initialFields(row, value.defaults ?? {}),
    ...value
  };
}
export function nameColumn(kind) {
  if (kind === void 0) {
    kind = 'icon';
  }
  return {
    key: 'name',
    title: 'Название',
    render: (row, lookups) => {
      const reference = kind === 'spell' ? lookup(lookups, 'paths', row.magic_path_id) : kind === 'item' ? lookup(lookups, 'item-types', row.item_type_id) : kind === 'attribute' ? lookup(lookups, 'attributes', row.attribute_id) : row;
      const image = kind === 'image' ? safeImage(text(row, 'image')) : '';
      return m("span", {
        className: "RpCatalog-name"
      }, image ? m("img", {
        src: image,
        alt: ""
      }) : m(Icon, {
        name: kind === 'race' ? uiIcon('sections.races') : catalogueIcon(text(reference ?? {}, 'icon')),
        style: {
          color: kind === 'spell' || kind === 'icon' && row.color ? pathColor(text(reference ?? {}, 'color')) : undefined
        }
      }), m("strong", {
        className: "RpCatalog-nameText",
        title: row.name
      }, row.name));
    }
  };
}
export function plainColumn(key, title) {
  return {
    key,
    title,
    render: row => key === 'name' ? m("span", {
      className: "RpCatalog-nameText",
      title: text(row, key)
    }, text(row, key) || '—') : text(row, key) || '—'
  };
}
export function listIcons(lookups, catalogue, value) {
  const selected = Array.isArray(value) ? value.map(Number) : [];
  return m("span", {
    className: "RpCatalog-icons"
  }, selected.length ? selected.map(id => {
    const row = lookup(lookups, catalogue, id);
    if (!row) return null;
    const image = safeImage(text(row, 'image'));
    return m("span", {
      key: id,
      title: row.name
    }, image ? m("img", {
      src: image,
      alt: ""
    }) : m(Icon, {
      name: catalogueIcon(text(row, 'icon'))
    }));
  }) : '—');
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/definitions/base', { statusFilter: statusFilter,referenceFilter: referenceFilter,definition: definition,nameColumn: nameColumn,plainColumn: plainColumn,listIcons: listIcons, });