import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import showModal from '../../../common/showModal';
import EventCreateModal from './EventCreateModal';
import { uiIcon } from '../../../common/uiIcons';
export default class EventCreateButton extends Component {
  view() {
    return m(Button, {
      type: "button",
      className: "Button Button--icon Button--link",
      icon: uiIcon('editor.event'),
      disabled: this.attrs.disabled,
      title: "\u0421\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F",
      "aria-label": "\u0421\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F",
      onclick: () => this.open()
    });
  }
  open() {
    const composer = this.attrs.composer,
      editor = composer.editor,
      body = composer.body;
    if (!editor || this.attrs.disabled) return;
    const [start] = editor.getSelectionRange();
    showModal(EventCreateModal, {
      oninsert: code => {
        if (composer.editor !== editor || composer.body !== body) throw new Error('Редактор изменился. Откройте создание события заново');
        editor.insertBetween(start, start, '\n' + code + '\n', true);
        this.attrs.onInserted?.();
      }
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/events/components/EventCreateButton', EventCreateButton);