import Feedback from '../../common/components/Feedback';
import Modal from '../../common/components/RoleplayModal';
import Button from 'flarum/common/components/Button';
/** До явного подтверждения ни персонаж, ни литературная тема не создаются. */
export default class CreationConfirmationModal extends Modal {
  pending = false;
  oninit(vnode) {
    super.oninit(vnode);
    const modal = this.attrs.state.modal;
    if (modal) modal.attrs = {
      ...modal.attrs,
      beforeRoleplayWizardClose: async () => !this.blocked()
    };
  }
  modalClassName() {
    return 'RpCreationConfirmModal';
  }
  modalHeading() {
    return {
      label: 'Подтверждение создания',
      purpose: 'create'
    };
  }
  blocked() {
    const wizard = this.attrs.wizard;
    return this.pending || wizard.busy || wizard.creating || wizard.uploading;
  }
  async act(action) {
    if (this.blocked()) return;
    this.pending = true;
    m.redraw();
    try {
      await action();
    } finally {
      this.pending = false;
      m.redraw();
    }
  }
  content() {
    const wizard = this.attrs.wizard;
    const payload = wizard.view.draft.payload;
    const name = [payload.first_name, payload.last_name].filter(Boolean).join(' ');
    return m("div", {
      className: "Modal-body"
    }, m("p", null, "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \u043D\u0430 \u0444\u043E\u0440\u0443\u043C\u0435 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0442\u0435\u043C\u0430 \u0441 \u0438\u043C\u0435\u043D\u0435\u043C \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430 ", m("strong", null, name), ". \u0425\u0443\u0434\u043E\u0436\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u0430\u044F \u0430\u043D\u043A\u0435\u0442\u0430 \u0432 \u043D\u0435\u0439 \u043F\u043E\u043A\u0430 \u0431\u0443\u0434\u0435\u0442 \u043F\u0443\u0441\u0442\u043E\u0439"), m("p", null, "\u0415\u0441\u043B\u0438 \u0432\u044B \u0445\u043E\u0442\u0438\u0442\u0435 \u0441\u0440\u0430\u0437\u0443 \u0440\u0430\u0437\u043C\u0435\u0441\u0442\u0438\u0442\u044C \u0433\u043E\u0442\u043E\u0432\u0443\u044E \u0430\u043D\u043A\u0435\u0442\u0443, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \xAB\u041E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A\xBB. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u044C\u0442\u0435 \u0445\u0443\u0434\u043E\u0436\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u0443\u044E \u0447\u0430\u0441\u0442\u044C \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u0442\u0435\u043C\u0435. \u041A\u043E\u0433\u0434\u0430 \u0432\u0441\u0451 \u0431\u0443\u0434\u0435\u0442 \u0433\u043E\u0442\u043E\u0432\u043E, \u0432\u0435\u0440\u043D\u0438\u0442\u0435\u0441\u044C \u0432 \u043C\u0430\u0441\u0442\u0435\u0440, \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u0438 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0438\u0442\u0435 BB-\u043A\u043E\u0434 \u0430\u043D\u043A\u0435\u0442\u044B \u0432 \u0441\u043E\u0437\u0434\u0430\u043D\u043D\u0443\u044E \u0442\u0435\u043C\u0443"), m("p", {
      className: "helpText"
    }, "\u0412\u0430\u0448 \u0432\u044B\u0431\u043E\u0440 \u0432 \u043C\u0430\u0441\u0442\u0435\u0440\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D \u2014 \u043A \u043D\u0435\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043F\u043E\u0437\u0436\u0435"), wizard.error && m(Feedback, {
      message: wizard.error
    }), m("div", {
      className: "RpCreationConfirm-actions"
    }, m(Button, {
      className: "Button",
      disabled: this.blocked(),
      onclick: () => void this.act(this.attrs.leaveDraft)
    }, "\u041E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A"), m(Button, {
      className: "Button Button--primary",
      loading: wizard.creating,
      disabled: this.blocked() || wizard.conflict,
      onclick: () => void this.act(this.attrs.confirm)
    }, "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430")));
  }
  onremove(vnode) {
    this.attrs.closed();
    super.onremove(vnode);
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/creation/CreationConfirmationModal', CreationConfirmationModal);