import app from 'flarum/forum/app';
export default class CheckApi {
  key = '';
  fingerprint = '';
  constructor(discussionId, requestId) {
    if (requestId === void 0) {
      requestId = null;
    }
    this.discussionId = discussionId;
    this.requestId = requestId;
  }
  query() {
    return {
      ...(this.discussionId ? {
        discussion_id: this.discussionId
      } : {}),
      ...(this.requestId ? {
        request_id: this.requestId
      } : {})
    };
  }
  base() {
    return app.forum.attribute('apiUrl') + '/roleplay/checks';
  }
  async context() {
    return (await app.request({
      method: 'GET',
      errorHandler: () => {},
      url: this.base() + '/context',
      params: this.query()
    })).data;
  }
  async character(id) {
    return (await app.request({
      method: 'GET',
      errorHandler: () => {},
      url: this.base() + '/characters/' + id,
      params: this.query()
    })).data;
  }
  async targets(search, page) {
    return (await app.request({
      method: 'GET',
      errorHandler: () => {},
      url: this.base() + '/targets',
      params: {
        ...this.query(),
        search,
        page
      }
    })).data;
  }
  async prepare(type, payload) {
    const fingerprint = JSON.stringify({
      type,
      payload
    });
    if (fingerprint !== this.fingerprint) {
      this.fingerprint = fingerprint;
      this.key = crypto.randomUUID();
    }
    return (await app.request({
      method: 'POST',
      errorHandler: () => {},
      url: this.base() + '/plans',
      body: {
        operation_key: this.key,
        discussion_id: this.discussionId,
        type,
        payload
      }
    })).data.code;
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/checks/CheckApi', CheckApi);