import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import { extend } from 'flarum/common/extend';
import Model from 'flarum/common/Model';
import { uiIcon } from '../../common/uiIcons';
class NotificationEvent extends Model {}

/** Штатный Notification рисует аватар, время, непрочитанность и кнопку прочтения. */
export default class CharacterNotification extends Notification {
  data() {
    return this.attrs.notification.content();
  }
  icon() {
    const kind = this.data().kind;
    return uiIcon(kind.startsWith('rank_') ? 'management.rank' : kind === 'mechanics_changes' ? 'actions.edit' : kind === 'literature_review' ? 'profile.literature' : kind.startsWith('remove_') || kind === 'deduction' ? 'management.remove' : kind.startsWith('grant_') || kind === 'reward' || kind === 'episode_reward' || kind === 'topic_reward' ? 'management.title' : 'actions.select');
  }
  href() {
    const data = this.data();
    if (data.kind === 'literature_approved' && data.discussionId) {
      return app.forum.attribute('baseUrl') + '/d/' + data.discussionId + (data.postNumber ? '/' + data.postNumber : '');
    }
    const user = app.session.user;
    return user ? app.route('user.roleplay', {
      username: user.slug()
    }) + '?character=' + data.characterId + '&event=' + data.eventId : '#';
  }
  content() {
    const data = this.data(),
      resources = [];
    for (const key of ['experience', 'gold']) {
      if (!data[key]) continue;
      if (resources.length) resources.push(' и ');
      resources.push(app.translator.trans('maxcuso-roleplay.forum.notifications.' + key, {
        amount: data[key]
      }));
    }
    return app.translator.trans('maxcuso-roleplay.forum.notifications.' + data.kind, {
      character: m("strong", null, data.characterName),
      name: m("strong", null, data.name ?? ''),
      resources,
      quantity: data.quantity && data.quantity > 1 ? ' ×' + data.quantity : ''
    });
  }
  excerpt() {
    return null;
  }
}
export function registerCharacterNotifications() {
  app.store.models['roleplay-events'] = NotificationEvent;
  for (const [type, icon] of [['roleplayReview', 'actions.select'], ['roleplayGrants', 'management.title'], ['roleplayRank', 'management.rank']]) {
    app.notificationComponents[type] = CharacterNotification;
    // Как у Арены: в Flarum 2 настройки загружаются отложенно, используем штатный поздний extend.
    extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
      items.add(type, {
        name: type,
        icon: uiIcon(icon),
        label: app.translator.trans('maxcuso-roleplay.forum.notification_settings.' + type)
      });
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/notifications/CharacterNotification', CharacterNotification);